import json, random, struct, subprocess, sys, zlib

def reference(request):
    pages = [bytearray.fromhex(p) for p in request['pages']]
    ckpt = request['checkpoint']
    log = bytes.fromhex(request['log'])
    pos, prev, last = 0, 0, 0
    act = {}  # tx -> [crc_accum, count, [(pg,off,data)]]
    while pos + 13 <= len(log):
        plen, seq, kind, tx = struct.unpack_from('<IIBI', log, pos)
        if plen > 4096: break
        end = pos + 17 + plen
        if end > len(log): break
        payload = log[pos+13:pos+13+plen]
        crc, = struct.unpack_from('<I', log, pos+13+plen)
        if zlib.crc32(log[pos:end-4]) & 0xffffffff != crc: break
        if not (seq > prev): break
        if kind not in (1,2,3,4) or tx < 1: break
        if kind == 2:
            if plen < 6: break
            pg, off, cnt = struct.unpack_from('<HHH', payload)
            if cnt == 0 or plen != 6 + cnt: break
            if pg >= len(pages) or off + cnt > len(pages[0]): break
        elif kind == 3:
            if plen != 8: break
        else:
            if plen != 0: break
        prev, last, pos = seq, seq, end
        if kind == 1:
            act[tx] = [0, 0, []]
        elif kind == 2:
            if tx in act:
                st = act[tx]
                st[0] = zlib.crc32(payload, st[0]) & 0xffffffff
                st[1] += 1
                st[2].append((pg, off, payload[6:]))
        elif kind == 4:
            act.pop(tx, None)
        else:
            st = act.pop(tx, None)
            if st is not None:
                cnt, dig = struct.unpack_from('<II', payload)
                if st[1] == cnt and st[0] == dig and seq > ckpt:
                    for pg, off, data in st[2]:
                        pages[pg][off:off+len(data)] = data
    return {'pages': [p.hex() for p in pages], 'valid_bytes': pos, 'last_seq': last}

def rec(seq, kind, tx, payload, corrupt=None):
    body = struct.pack('<IIBI', len(payload), seq, kind, tx) + payload
    if corrupt == 'crc':
        return body + struct.pack('<I', (zlib.crc32(body) & 0xffffffff) ^ 0xff)
    return body + struct.pack('<I', zlib.crc32(body) & 0xffffffff)

def pload(pg, off, data):
    return struct.pack('<HHH', pg, off, len(data)) + data

def gen_log(rng, npages, psize):
    """Build a random log; returns bytes."""
    seq = 0
    out = b''
    staged = {}
    nrec = rng.randint(0, 12)
    for _ in range(nrec):
        seq += rng.randint(1, 3)
        r = rng.random()
        tx = rng.choice([1, 1, 2, 2, 3, 7])
        if r < 0.3:
            out += rec(seq, 1, tx, b''); staged[tx] = []
        elif r < 0.6:
            cnt = rng.randint(1, psize)
            pg = rng.randrange(npages); off = rng.randint(0, psize - cnt)
            data = bytes(rng.randrange(256) for _ in range(cnt))
            out += rec(seq, 2, tx, pload(pg, off, data))
            if tx in staged: staged[tx].append(pload(pg, off, data))
        elif r < 0.8:
            ps = staged.get(tx)
            if ps is not None and rng.random() < 0.85:
                blob = b''.join(ps)
                c, d = len(ps), zlib.crc32(blob) & 0xffffffff
                if rng.random() < 0.2: c += rng.randint(1, 3)      # count mismatch
                elif rng.random() < 0.2: d ^= 0x1234                # digest mismatch
                out += rec(seq, 3, tx, struct.pack('<II', c, d))
            else:
                out += rec(seq, 3, tx, struct.pack('<II', 0, 0))   # orphan commit
            staged.pop(tx, None)
        else:
            out += rec(seq, 4, tx, b''); staged.pop(tx, None)
    # possible corruption / garbage at the end
    r = rng.random()
    if r < 0.25:
        out = out[:rng.randint(0, len(out))]                        # truncate mid-record
    elif r < 0.45:
        out += bytes(rng.randrange(256) for _ in range(rng.randint(1, 30)))
    elif r < 0.6 and out:
        i = rng.randrange(len(out)); out = out[:i] + bytes([out[i] ^ 0xff]) + out[i+1:]
    # fully invalid records sprinkled
    if rng.random() < 0.3:
        kind = rng.choice([0, 5, 200, 1, 2, 3, 4])
        tx = rng.choice([0, 1])
        pl = rng.choice([b'', b'xx', bytes(5000)])
        out += rec(seq + rng.randint(1, 5), kind, tx, pl)
    return out

def main():
    rng = random.Random(20240813)
    cases = []
    for i in range(600):
        npages = rng.randint(1, 8)
        psize = rng.randint(1, 64)
        pages = [''.join(rng.choice('0123456789abcdef') for _ in range(2*psize)) for _ in range(npages)]
        if rng.random() < 0.2: pages = [p.upper() for p in pages]
        log = gen_log(rng, npages, psize)
        ckpt = rng.choice([0, 0, 1, rng.randint(0, 40), 10**9])
        req = {'pages': pages, 'checkpoint': ckpt, 'log': log.hex()}
        cases.append((req, reference(req)))

    inp = ''.join(json.dumps(r)+'\n' for r, _ in cases)
    p = subprocess.run([sys.executable, '/app/main.py'], input=inp, text=True,
                       capture_output=True, cwd='/app')
    assert p.returncode == 0, p.stderr
    lines = p.stdout.splitlines()
    assert len(lines) == len(cases), (len(lines), len(cases))
    bad = 0
    for i, ((req, exp), line) in enumerate(zip(cases, lines)):
        got = json.loads(line)
        if got != exp:
            bad += 1
            print(f"MISMATCH case {i}\n  req={json.dumps(req)}\n  exp={exp}\n  got={got}")
            if bad > 4: break
    print(f"{len(cases)-bad}/{len(cases)} randomized cases match reference")
    sys.exit(1 if bad else 0)

if __name__ == '__main__':
    main()
